function longestSharedLead(a: number[], b: number[]): number {
  type Node = Map<string, Node>;
  const root: Node = new Map();
  for (const x of a) {
    let node = root;
    for (const ch of String(x)) {
      if (!node.has(ch)) node.set(ch, new Map());
      node = node.get(ch)!;
    }
  }
  let best = 0;
  for (const y of b) {
    let node = root, depth = 0;
    for (const ch of String(y)) {
      const next = node.get(ch);
      if (!next) break;
      node = next;
      depth++;
    }
    best = Math.max(best, depth);
  }
  return best;
}

